const existing = new Set(
  $('讀取已有單字').all().map((i) => {
    const r = i.json?.row ?? i.json ?? {};
    return String(r.word ?? '').trim().toLowerCase();
  }).filter(Boolean)
);
const seen = new Set();
const rows = [];
let totalParsed = 0, skippedExisting = 0, skippedDup = 0, skippedInvalid = 0;
for (const item of $input.all()) {
  const j = item.json ?? {};
  let raw = j.text ?? j.output ?? j.content ?? '';
  if (typeof raw !== 'string') raw = JSON.stringify(j);
  raw = String(raw).replace(/```json/gi, '').replace(/```/g, '').trim();
  let arr;
  try { arr = JSON.parse(raw); }
  catch (e) {
    const m = String(raw).match(/\[[\s\S]*\]/);
    if (!m) { skippedInvalid++; continue; }
    try { arr = JSON.parse(m[0]); } catch (e2) { skippedInvalid++; continue; }
  }
  if (!Array.isArray(arr)) { skippedInvalid++; continue; }
  for (const w of arr) {
    totalParsed++;
    const word = String(w.word ?? '').trim();
    const meaning_zh = String(w.meaning_zh ?? '').trim();
    const pos = String(w.pos ?? '').trim();
    const example_en = String(w.example_en ?? '').trim();
    if (!/^[A-Za-z][A-Za-z'\- ]{1,30}$/.test(word)) { skippedInvalid++; continue; }
    if (!meaning_zh) { skippedInvalid++; continue; }
    const key = word.toLowerCase();
    if (existing.has(key)) { skippedExisting++; continue; }
    if (seen.has(key)) { skippedDup++; continue; }
    seen.add(key);
    rows.push({ json: {
      word,
      meaning_zh,
      extra: '',
      pos,
      progress: '不熟',
      example_en,
      tts_url: 'https://translate.google.com/translate_tts?ie=UTF-8&tl=en&client=tw-ob&q=' + encodeURIComponent(word)
    }});
  }
}
if (rows.length === 0) {
  throw new Error('組裝單字卡：無可用新單字（解析:' + totalParsed + ' 已存在:' + skippedExisting + ' 批次內重複:' + skippedDup + ' 無效:' + skippedInvalid + '）。請檢查 Ollama 回傳是否為純 JSON 陣列。');
}
return rows;

const items = $input.all().map((i) => i.json?.row || i.json).filter((r) => r && String(r.word || '').trim());
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const escAttr = (s) => esc(s).replace(/'/g, '&#39;');
const cards = items.map((r) => {
  const word = esc(r.word);
  const key = escAttr(String(r.word ?? '').toLowerCase());
  return '<article class="card" data-word="' + key + '" data-meaning="' + escAttr(r.meaning_zh) + '"><h2>' + word + '</h2><div class="meta"><span class="badge">解釋：' + esc(r.meaning_zh) + '</span><span class="badge">補充：' + esc(r.extra || 'Empty') + '</span><span class="badge pos">' + esc(r.pos) + '</span><span class="badge prog">' + esc(r.progress || '不熟') + '</span></div><p class="ex">' + esc(r.example_en) + '</p><div class="row"><audio controls preload="none" src="' + escAttr(r.tts_url) + '"></audio><button onclick="mark(\'' + key + '\',\'已會\')">已會</button><button onclick="mark(\'' + key + '\',\'不熟\')">不熟</button></div></article>';
}).join('\n');
const html = '<!DOCTYPE html><html lang="zh-Hant"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>英文單字卡</title><style>body{font-family:sans-serif;max-width:900px;margin:0 auto;padding:16px}.toolbar{position:sticky;top:0;background:#fff;padding:8px 0;display:flex;gap:8px}.card{border:1px solid #ddd;border-radius:12px;padding:16px;margin:12px 0}.card h2{font-size:2em;margin:0 0 8px}.badge{display:inline-block;background:#f2f2f2;border-radius:6px;padding:2px 8px;margin:2px 4px 2px 0;font-size:.85em}.pos{background:#fef3c7}.ex{margin:12px 0}.row{display:flex;gap:8px;align-items:center}.hint{color:#666;font-size:.85em}#focus{border:2px solid #333;border-radius:12px;padding:8px;margin:12px 0}</style></head><body><h1>英文單字卡共 ' + items.length + ' 張</h1><p class="hint">進度（已會/不熟）僅保存在此瀏覽器 localStorage，換裝置不會同步；發音取自 Google TTS，可能失效。</p><div class="toolbar"><input id="q" placeholder="搜尋單字或中文" oninput="filter()" style="flex:1;padding:8px"><button onclick="random()">隨機抽卡</button></div><div id="focus"></div><div id="list">' + cards + '</div><script>var prog=JSON.parse(localStorage.getItem(\'vocabProg\')||\'{}\');function paint(){document.querySelectorAll(\'.prog\').forEach(function(b){var w=b.closest(\'.card\').dataset.word;if(prog[w])b.textContent=prog[w];});}function mark(w,s){prog[String(w||\'\').toLowerCase()]=s;localStorage.setItem(\'vocabProg\',JSON.stringify(prog));paint();}function filter(){var q=document.getElementById(\'q\').value.toLowerCase();document.querySelectorAll(\'#list .card\').forEach(function(c){c.style.display=(c.dataset.word.indexOf(q)>-1||c.dataset.meaning.indexOf(q)>-1)?\'\':\'none\';});}function random(){var cs=[...document.querySelectorAll(\'#list .card\')].filter(function(c){return c.style.display!==\'none\';});if(!cs.length)return;var c=cs[Math.floor(Math.random()*cs.length)];var f=document.getElementById(\'focus\');f.innerHTML=\'<h3>隨機抽卡</h3>\';f.appendChild(c.cloneNode(true));window.scrollTo(0,0);}paint();</script></body></html>';
return [{ json: { html } }];

const letters = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ'.split('');
const topics = ['職場溝通','旅遊交通','餐飲美食','科技網路','健康醫療','教育學習','商業金融','環境氣候','運動休閒','文化藝術','政治法律','科學研究','家庭生活','購物消費','社交情感','日常時間','自然動物','城市生活','求職面試','商務書信','會議簡報','客服應對','天氣季節','興趣愛好'];
const seeds = [
  ...letters.map((L) => ({ json: { hint: `以 ${L} 開頭的常用英文單字` } })),
  ...topics.map((t) => ({ json: { hint: `主題「${t}」相關的常用英文單字` } })),
];
return seeds;
